package in.ac.rtu.medicare.dao;
import in.ac.rtu.medicare.config.Database; import in.ac.rtu.medicare.model.Appointment; import java.sql.*; import java.time.*; import java.util.*;
public class AppointmentDao {
 public long patientIdForUser(long userId)throws SQLException{return scalar("SELECT id FROM patients WHERE user_id=?",userId);}
 public long doctorIdForUser(long userId)throws SQLException{return scalar("SELECT id FROM doctors WHERE user_id=?",userId);}
 public long create(long patient,long doctor,LocalDateTime at,String reason)throws SQLException {try(Connection c=Database.connection()){c.setTransactionIsolation(Connection.TRANSACTION_SERIALIZABLE);c.setAutoCommit(false);try{if(conflict(c,doctor,at))throw new IllegalStateException("Doctor already has an active appointment in this time slot");try(PreparedStatement s=c.prepareStatement("INSERT INTO appointments(patient_id,doctor_id,appointment_at,reason) VALUES(?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){s.setLong(1,patient);s.setLong(2,doctor);s.setTimestamp(3,Timestamp.valueOf(at));s.setString(4,reason);s.executeUpdate();try(ResultSet k=s.getGeneratedKeys()){k.next();c.commit();return k.getLong(1);}}}catch(SQLException|RuntimeException e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}}
 private boolean conflict(Connection c,long d,LocalDateTime at)throws SQLException {try(PreparedStatement s=c.prepareStatement("SELECT 1 FROM appointments WHERE doctor_id=? AND status='BOOKED' AND appointment_at >= ? AND appointment_at < ? FOR UPDATE")){s.setLong(1,d);s.setTimestamp(2,Timestamp.valueOf(at.minusMinutes(29)));s.setTimestamp(3,Timestamp.valueOf(at.plusMinutes(30)));try(ResultSet r=s.executeQuery()){return r.next();}}}
 public void cancel(long id,long patient)throws SQLException {try(Connection c=Database.connection();PreparedStatement s=c.prepareStatement("UPDATE appointments SET status='CANCELLED',cancelled_at=NOW() WHERE id=? AND patient_id=? AND status='BOOKED' AND appointment_at>NOW()")){s.setLong(1,id);s.setLong(2,patient);if(s.executeUpdate()!=1)throw new IllegalStateException("Appointment cannot be cancelled");}}
 public void complete(long id,long doctor)throws SQLException {try(Connection c=Database.connection();PreparedStatement s=c.prepareStatement("UPDATE appointments SET status='COMPLETED' WHERE id=? AND doctor_id=? AND status='BOOKED'")){s.setLong(1,id);s.setLong(2,doctor);if(s.executeUpdate()!=1)throw new IllegalStateException("Appointment cannot be completed");}}
 public List<Appointment> forPatient(long patient)throws SQLException{return list("SELECT * FROM appointments WHERE patient_id=? ORDER BY appointment_at DESC",patient);}
 public List<Appointment> forDoctor(long doctor)throws SQLException{return list("SELECT * FROM appointments WHERE doctor_id=? ORDER BY appointment_at DESC",doctor);}
 private List<Appointment> list(String q,long v)throws SQLException {List<Appointment>x=new ArrayList<>();try(Connection c=Database.connection();PreparedStatement s=c.prepareStatement(q)){s.setLong(1,v);try(ResultSet r=s.executeQuery()){while(r.next())x.add(new Appointment(r.getLong("id"),r.getLong("patient_id"),r.getLong("doctor_id"),r.getTimestamp("appointment_at").toLocalDateTime(),r.getString("reason"),r.getString("status")));}}return x;}
 private long scalar(String q,long id)throws SQLException {try(Connection c=Database.connection();PreparedStatement s=c.prepareStatement(q)){s.setLong(1,id);try(ResultSet r=s.executeQuery()){if(!r.next())throw new IllegalStateException("Profile is not configured");return r.getLong(1);}}}
}
